    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'Which of the following is the primary goal of palliative care?', '["To cure the underlying disease", "To prolong life at any cost", "To optimize quality of life by anticipating, preventing, and treating suffering", "To assist in physician-assisted suicide"]', 2, 'Palliative care focuses on quality of life and relief of suffering, regardless of the stage of the disease or the need for other therapies.'),
    (v_topic_id, 'A 68-year-old patient with metastatic lung cancer is referred for hospice care. What is the standard life expectancy requirement for hospice eligibility in the United States?', '["Less than 1 year", "Less than 6 months", "Less than 3 months", "Less than 1 month"]', 1, 'Hospice eligibility generally requires a physician certification that the patient has a life expectancy of 6 months or less if the disease runs its normal course.'),
    (v_topic_id, 'The "Rule of Double Effect" is frequently applied in end-of-life pain management. It states that an action with a good intent is ethically permissible even if it has a foreseeable bad effect. Which of the following is the "good intent" in this context?', '["Hastening death", "Relieving suffering/pain", "Saving hospital resources", "Reducing the nursing workload"]', 1, 'The Rule of Double Effect justifies the use of high-dose opioids for pain relief even if they may foreseeably cause respiratory depression, provided the primary intent is comfort.'),
    (v_topic_id, 'Which of the following best describes "Hospice" care?', '["It is only provided in a hospital setting", "It is a philosophy of care that can be delivered in homes, nursing facilities, or dedicated centers", "It requires the patient to continue curative treatments", "It is only for patients with cancer"]', 1, 'Hospice is a model of palliative care for patients at the end of life, emphasizing comfort over cure, and can be provided in various settings.'),
    (v_topic_id, 'A patient in the final stages of a terminal illness experiences "Terminal Restlessness." What is the first-line pharmacological approach for symptom management?', '["Intubation and sedation", "High-dose morphine", "Neuroleptics (e.g., Haloperidol) or benzodiazepines", "Stimulants to improve clarity"]', 2, 'Terminal restlessness/delirium is often managed with neuroleptics or benzodiazepines to provide comfort and safety.'),
    (v_topic_id, 'In the context of end-of-life care, "Total Pain" refers to:', '["Pain that covers the entire body", "Pain that cannot be treated", "The combination of physical, psychological, social, and spiritual suffering", "Pain that requires general anesthesia"]', 2, 'Total pain is a foundational palliative care concept emphasizing that suffering has multiple dimensions beyond just physical nociception.'),
    (v_topic_id, 'A patient with end-of-life dyspnea is most effectively treated with which class of medication?', '["Bronchodilators", "Low-dose opioids", "Diuretics", "Supplemental oxygen (even if not hypoxic)"]', 1, 'Opioids are the gold standard for relieving the sensation of dyspnea in terminal patients by reducing the drive to breathe and the perception of breathlessness.'),
    (v_topic_id, 'Which of the following is a common barrier to effective palliative care referral?', '["The misconception that it means ''giving up''", "The high cost compared to curative care", "Lack of evidence for its effectiveness", "Patient refusal to speak with doctors"]', 0, 'Cultural and medical misconceptions that palliative care is synonymous with imminent death often delay beneficial referrals.'),
    (v_topic_id, 'The "Spikes" protocol is a widely used tool for what clinical task?', '["Managing acute pain", "Breaking bad news", "Assessing surgical risk", "Determining hospice eligibility"]', 1, 'SPIKES (Setting, Perception, Invitation, Knowledge, Emotions, Strategy) is a framework for communicating difficult information to patients and families.'),
    (v_topic_id, 'Which of the following is TRUE regarding palliative care for pediatric patients?', '["It is only for children with cancer", "It can be provided concurrently with life-prolonging or curative treatments", "Children must be over 12 to receive it", "It is prohibited by most insurance plans"]', 1, 'Unlike adult hospice, pediatric palliative care is often integrated with curative efforts from the time of diagnosis of a life-threatening condition.'),
    (v_topic_id, 'When transitioning a patient to hospice, the "Medicare Hospice Benefit" requires the patient to:', '["Pay a high monthly deductible", "Waive their right to curative treatments for their terminal illness", "Move into a skilled nursing facility", "Have at least two family members as primary caregivers"]', 1, 'Choosing the hospice benefit generally involves electing to focus on comfort care rather than curative interventions for the terminal diagnosis.'),
    (v_topic_id, 'A terminal patient expresses a wish to "Stop eating and drinking." This is known as:', '["Suicide", "Voluntarily Stopping Eating and Drinking (VSED)", "Medical neglect", "Euthanasia"]', 1, 'VSED is a legally and ethically recognized choice for competent terminal patients to hasten death by refusing nutrition and hydration.'),
    (v_topic_id, 'Which ethical principle is primarily invoked when a patient chooses to refuse life-sustaining treatment?', '["Justice", "Beneficence", "Autonomy", "Non-maleficence"]', 2, 'Autonomy—the right to self-determination—is the foundation for a patient''s right to refuse any medical intervention.'),
    (v_topic_id, 'A patient is experiencing "Death Rattle" (noisy secretions). Which class of medication is typically used?', '["Antibiotics", "Anticholinergics (e.g., Glycopyrrolate)", "Expectorants", "Inhaled steroids"]', 1, 'Anticholinergics help dry up oropharyngeal secretions that cause the rattling sound, which can be distressing for families.'),
    (v_topic_id, 'Which of the following is a "Physical" sign of imminent death?', '["Increased appetite", "Cheyne-Stokes respirations", "Increased urine output", "Hypertension"]', 1, 'Cheyne-Stokes breathing (apnea followed by hyperpnea) is a classic sign of the dying process.'),
    (v_topic_id, 'The principle of "Non-maleficence" in end-of-life care would most strongly argue AGAINST:', '["Providing high-dose pain relief", "Performing invasive, painful procedures with no clinical benefit", "Allowing a patient to go home to die", "Holding a family meeting"]', 1, 'Non-maleficence (Do No Harm) prohibits the use of burdensome treatments that do not provide meaningful benefit or relief.'),
    (v_topic_id, 'In palliative care, the "Intention" of the clinician is the deciding factor in the Rule of Double Effect. What must the clinician NOT intend?', '["The patient''s comfort", "The relief of respiratory distress", "The death of the patient", "The reduction of pain"]', 2, 'The bad effect (death) must not be the intended goal, even if it is a foreseeable outcome of providing necessary comfort care.'),
    (v_topic_id, 'Which of the following describes "Palliative Sedation"?', '["Giving a patient a sleeping pill", "The use of sedative medications to relieve refractory suffering in terminal patients, which may result in a reduced level of consciousness", "General anesthesia for a minor surgery", "Assisted suicide using pills"]', 1, 'Palliative sedation is used as a last resort for terminal symptoms (like intractable pain or delirium) that cannot be managed by other means.'),
    (v_topic_id, 'A patient''s family asks, "How long do we have?" The physician should:', '["Give a specific date and time", "Avoid the question entirely", "Provide a range of time (hours to days, or days to weeks) based on clinical signs, while emphasizing uncertainty", "Tell them the patient will live for another year"]', 2, 'Providing a range and managing expectations with humility regarding the uncertainty of timing is the most helpful and honest approach.'),
    (v_topic_id, 'Which of the following is a benefit of early palliative care integration in cancer patients?', '["Longer hospital stays", "Improved quality of life and, in some studies, improved survival", "Higher healthcare costs", "More aggressive chemotherapy use"]', 1, 'Evidence shows that early palliative care improves both quality of life and potentially survival compared to standard care alone.'),
    (v_topic_id, 'The "Best Interest Standard" is used for decision-making when:', '["The patient is competent", "The patient''s prior wishes are clearly known", "The patient is incapacitated and their prior wishes are unknown or cannot be inferred", "The doctor wants to try a new drug"]', 2, 'When a surrogate has no evidence of what the patient would have wanted, they must decide based on what would provide the most benefit and least harm (Best Interest).'),
    (v_topic_id, 'Which of the following is a core component of "Spiritual Care" in palliative medicine?', '["Converting the patient to a specific religion", "Exploring the patient''s sources of meaning, hope, and connection", "Giving the patient a Bible", "Telling the patient their suffering is a test"]', 1, 'Spiritual care is broad and focuses on the patient''s own values and existential needs, rather than dogma.'),
    (v_topic_id, 'Bereavement support for families is a required component of:', '["Intensive care", "Hospice care", "Standard outpatient visits", "Emergency room visits"]', 1, 'Hospice care is unique in that it includes support for the family for at least one year following the patient''s death.'),
    (v_topic_id, 'Which of the following is an "End-of-life" communication pitfall?', '["Using the words ''death'' and ''dying'' clearly", "Using euphemisms like ''expired'' or ''passed away'' that can cause confusion", "Listening more than talking", "Validating emotions"]', 1, 'Clear language is essential; euphemisms can lead to misunderstandings during highly emotional times.'),
    (v_topic_id, 'A "Good Death" as defined by many palliative researchers includes all EXCEPT:', '["Control over the dying process", "Pain and symptom management", "A prolonged ICU stay on a ventilator", "Preparation for death"]', 2, 'A prolonged, highly medicalized death in an ICU is often cited as the opposite of what patients and families consider a "good death."'),
    (v_topic_id, 'The "Four Pillars" of medical ethics include all of the following EXCEPT:', '["Autonomy", "Efficiency", "Justice", "Beneficence"]', 1, 'Efficiency is a goal of health systems, but not one of the four foundational principles of clinical ethics (which are Autonomy, Beneficence, Non-maleficence, and Justice).'),
    (v_topic_id, 'Which of the following is TRUE about the withdrawal of a ventilator at the end of life?', '["It is considered active euthanasia", "It is legally and ethically equivalent to withholding the ventilator in the first place", "It is only allowed if the patient is brain dead", "It requires a court order in all 50 states"]', 1, 'The ethical consensus is that there is no moral or legal distinction between not starting a treatment and stopping one that is no longer beneficial.'),
    (v_topic_id, 'What is the "First Step" in the SPIKES protocol?', '["Setting up the interview (Privacy, involving family)", "Perception (What does the patient know?)", "Invitation (How much does the patient want to know?)", "Knowledge (Giving the info)"]', 0, 'Preparation (Setting) is the first step—ensuring a quiet, private, and uninterrupted space for the conversation.'),
    (v_topic_id, 'A patient on hospice survives longer than 6 months. What happens to their hospice status?', '["They are kicked out immediately", "They can be recertified for another period if a physician still determines their life expectancy is < 6 months", "They are charged for the extra time", "They must go to court"]', 1, 'Hospice is not a "one-shot" benefit; it can be renewed indefinitely as long as the clinical criteria are met.'),
    (v_topic_id, 'Which of the following is a common symptom of "Caregiver Burden" in end-of-life care?', '["Increased energy", "Social isolation and depression", "A sense of being over-insured", "None of the above"]', 1, 'Caring for a terminal loved one is physically and emotionally taxing, often leading to significant caregiver distress.'),
    (v_topic_id, 'The "Palliative Performance Scale" (PPS) is primarily used to:', '["Measure pain", "Assess functional status and help determine prognosis", "Calculate the bill", "Assess religious faith"]', 1, 'The PPS is a modification of the Karnofsky Scale used in palliative care to track a patient''s decline and assist in planning.'),
    (v_topic_id, 'Which of the following is an ethical requirement for "Palliative Sedation to Unconsciousness" (PSU)?', '["The patient must be able to walk", "The symptoms must be refractory (unresponsive to standard treatments)", "The family must pay a fee", "The patient must have no insurance"]', 1, 'PSU is reserved for truly refractory suffering where all other interventions have failed.'),
    (v_topic_id, 'In the "SPIKES" protocol, the "E" stands for:', '["Efficiency", "Empathy", "Education", "Evaluation"]', 1, 'Empathy involves identifying and validating the patient''s or family''s emotions in response to bad news.'),
    (v_topic_id, 'Which of the following is NOT a component of a hospice interdisciplinary team?', '["Chaplain", "Social Worker", "Marketing Executive", "Nurse Case Manager"]', 2, 'While companies have marketing departments, the clinical interdisciplinary team (IDT) is composed of doctors, nurses, social workers, chaplains, and aides.'),
    (v_topic_id, 'A patient with end-stage dementia has stopped eating. The family asks for a "Feeding Tube." The physician should explain:', '["Feeding tubes are mandatory", "Feeding tubes do not prolong life or improve comfort in advanced dementia and may increase the risk of aspiration", "Feeding tubes are easy to maintain", "Feeding tubes are only for young people"]', 1, 'Evidence shows that artificial nutrition does not provide clinical benefit in advanced dementia and can cause more harm (infections, restraints, aspiration).'),
    (v_topic_id, 'Which of the following is a "Barrier" to effective pain management at the end of life?', '["Fear of addiction in a terminal patient", "Concern about the Rule of Double Effect", "Lack of knowledge about equianalgesic dosing", "All of the above"]', 3, 'Myths about addiction and lack of pharmacological knowledge often result in undertreated pain.'),
    (v_topic_id, 'What is the role of a "Child Life Specialist" in pediatric palliative care?', '["To give injections", "To help children and siblings cope with illness and loss through play and developmental support", "To manage the budget", "To teach the children math"]', 1, 'Child life specialists are critical for the emotional and developmental well-being of the patient and their family.'),
    (v_topic_id, 'Which of the following is the most reliable indicator of pain in a non-verbal terminal patient?', '["Heart rate", "Blood pressure", "The patient''s facial expressions and behavioral indicators (e.g., moaning, guarding)", "The family''s opinion"]', 2, 'Behavioral scales (like FLACC or PAINAD) are used to assess pain when a patient cannot self-report.'),
    (v_topic_id, 'A "Concurrent Care" model in pediatrics refers to:', '["Two doctors in the same room", "Providing both curative and hospice-like services simultaneously", "Caring for a child and an adult together", "None of the above"]', 1, 'This model (mandated by the ACA for Medicaid children) allows for aggressive treatment to continue while receiving palliative support.'),
    (v_topic_id, 'The "Living Will" is a type of:', '["Advance Directive", "Insurance policy", "Last Will and Testament", "Birth certificate"]', 0, 'A Living Will is a legal document specifying a person''s wishes regarding medical treatment when they are no longer able to give informed consent.'),
    (v_topic_id, 'Which of the following is a "Non-pharmacological" intervention for dyspnea?', '["A cool fan blowing on the face", "Closing all windows", "Giving a heavy meal", "Intense exercise"]', 0, 'A cool breeze/fan stimulates the trigeminal nerve and can reduce the sensation of breathlessness.'),
    (v_topic_id, 'A patient on hospice wants to visit the ER for a broken hip. Does hospice pay for this?', '["Yes, always", "Only if it was pre-authorized and related to the terminal illness, otherwise the patient may have to ''revoke'' hospice or pay out of pocket", "No, never", "Hospice pays for everything"]', 1, 'Coordination of care is critical; unapproved visits to the ER for non-terminal issues can complicate hospice coverage.'),
    (v_topic_id, 'Which of the following is TRUE about "Pain" at the end of life?', '["It is inevitable", "It can be managed in the vast majority of patients with proper palliative care", "It is only for people with cancer", "It always requires IV medication"]', 1, 'While common, terminal pain is highly manageable with current medical knowledge.'),
    (v_topic_id, 'The "Patient Self-Determination Act" (PSDA) requires hospitals to:', '["Force patients to sign a DNR", "Inform patients of their right to make advance directives and provide information on how to do so", "Pay for the patient''s lawyer", "None of the above"]', 1, 'The PSDA ensures that patients are empowered to plan for their future care.'),
    (v_topic_id, 'A "Proxy" or "Surrogate" is:', '["The doctor", "A person authorized to make medical decisions for another person who has lost capacity", "The hospital CEO", "A police officer"]', 1, 'Surrogates act as the patient''s voice when the patient can no longer speak.'),
    (v_topic_id, 'Which of the following is a "Psychological" symptom of end-of-life distress?', '["Constipation", "Existential anguish and fear of being a burden", "Fever", "Cough"]', 1, 'Existential and psychological suffering are just as important to address as physical symptoms.'),
    (v_topic_id, 'A patient is in a "Persistent Vegetative State" (PVS). What is their level of awareness?', '["Fully aware but paralyzed", "Wakeful but no evidence of awareness of self or environment", "Completely dead", "Dreaming"]', 1, 'PVS is characterized by sleep-wake cycles but a total lack of cognitive function or environmental interaction.'),
    (v_topic_id, 'Which of the following is an "Altruistic" reason some patients choose to stop treatment?', '["To save money for their children", "To avoid being a burden to their family", "To allow their organs to be donated", "All of the above"]', 3, 'Patients often weigh their own quality of life against the impact of their illness on their loved ones.'),
    (v_topic_id, 'In palliative care, "Grief" is considered:', '["A disease to be cured", "A normal response to loss", "Something that only happens after death", "Only for children"]', 1, 'Grief is a natural process that often begins long before the actual death (anticipatory grief).'),
    (v_topic_id, 'A physician who refuses to follow a valid advance directive for personal moral reasons should:', '["Ignore the document", "Sue the patient", "Transfer the patient''s care to another physician who is willing to honor the patient''s wishes", "Quit medicine"]', 2, 'While physicians have a right to "conscientious objection," they must not abandon the patient and must facilitate a transfer of care.')
